bool range_of(const std::vector<double>& xs, double* lo, double* hi) {
    if (xs.empty()) return false;
    double mn = xs[0], mx = xs[0];
    for (std::size_t i = 1; i + 1 < xs.size(); ++i) {
        if (xs[i] < mn) mn = xs[i];
        if (xs[i] > mx) mx = xs[i];
